parameters.jsCode:
// Pega quem ainda não recebeu este disparo e monta o envio dos próximos N (igual ao "Montar envio" do 5.1b).
const cfg = $('Config').first().json;
const d = $('Busca disparo').first().json;
const LOTE = Number(cfg.lote) || 100;

function normalizeTelefone(raw) {
  if (raw == null) return '';
  let t = String(raw).replace(/\D/g, '').replace(/^0+/, '');
  if (!t) return '';
  if (t.startsWith('55')) t = t.slice(2);
  if (t.length === 10 && ['6', '7', '8', '9'].includes(t[2])) t = t.slice(0, 2) + '9' + t.slice(2);
  return '55' + t;
}

const processados = new Set(
  $('Já processados').all().map(i => i.json.telefone).filter(Boolean)
);

const vistos = new Set();
const lote = [];
let pendentes = 0;

for (const { json: p } of $('Base de parceiros').all()) {
  const telefone = normalizeTelefone(p.whatsapp);
  if (!telefone || telefone.length < 12) continue;   // telefone inválido: ignora
  if (vistos.has(telefone)) continue;                // mesmo telefone em 2 cadastros: uma vez só
  vistos.add(telefone);
  if (processados.has(telefone)) continue;           // já recebeu (ou já deu erro definitivo)
  pendentes++;
  if (lote.length >= LOTE) continue;

  const nome = String(p.clientes || '').trim();
  const primeiroNome = nome.split(' ')[0] || 'tudo bem';
  const comps = [];
  if (d.tipo_midia === 'imagem' && d.imagem_url) {
    comps.push({ type: 'header', parameters: [{ type: 'image', image: { link: d.imagem_url } }] });
  }

  // Variáveis do template: o sistema grava em "variaveis" qual dado do parceiro vai em cada {{n}}.
  // Se o cadastro não tiver o dado, usa um texto genérico (a Meta recusa variável vazia).
  const CAMPOS = {
    nome:    primeiroNome,
    empresa: String(p.empresa || '').trim() || 'sua empresa',
    cidade:  String(p.cidade || '').trim()  || 'sua cidade',
    uf:      String(p.uf || '').trim()      || 'seu estado',
  };
  let vars = d.variaveis;
  if (typeof vars === 'string') { try { vars = JSON.parse(vars); } catch (e) { vars = []; } }
  if (!Array.isArray(vars)) vars = [];
  if (vars.length === 0 && d.usa_nome) vars = [{ indice: 1, campo: 'nome' }]; // disparos antigos
  vars = [...vars].sort((a, b) => a.indice - b.indice);
  const valores = vars.map(v => CAMPOS[v.campo] ?? '');
  if (valores.length) {
    comps.push({ type: 'body', parameters: valores.map(t => ({ type: 'text', text: t })) });
  }
  let mensagemFinal = String(d.mensagem || '');
  vars.forEach((v, i) => { mensagemFinal = mensagemFinal.replaceAll(`{{${v.indice}}}`, valores[i]); });

  lote.push({ json: {
    disparo_id: d.id,
    mailing_id: p.id,
    nome,
    primeiro_nome: primeiroNome,
    telefone,
    template_name: d.template_name,
    mensagem: mensagemFinal,
    url: `https://graph.facebook.com/v22.0/${cfg.phone_id}/messages`,
    meta_body: {
      messaging_product: 'whatsapp',
      to: telefone,
      type: 'template',
      template: { name: d.template_name, language: { code: d.language_code || 'pt_BR' }, components: comps },
    },
  }});
}

if (lote.length === 0) {
  return [{ json: { vazio: true, total_base: vistos.size } }];
}
return lote.map(i => ({ json: { ...i.json, vazio: false, pendentes_antes: pendentes } }));

// Run Once for Each Item: converte a resposta da Meta. Falha temporária vira 'retry' (volta no próximo lote).
const RETRY_CODES = [4, 80007, 130429, 131000, 131016, 131048, 133004];
const l = $('Loop Envio').item.json;
const r = $json;
const status = Number(r.statusCode ?? 0);
const body = r.body ?? r;
const wamid = body?.messages?.[0]?.id ?? null;
const ok = status >= 200 && status < 300 && !!wamid;
const code = Number(body?.error?.code ?? 0);
const retry = !ok && (status === 0 || status === 429 || status >= 500 || RETRY_CODES.includes(code));
const erro = ok ? null
  : body?.error ? `[${code}] ${body.error.message ?? ''} ${body.error.error_data?.details ?? ''}`.trim()
  : (r.error?.message ?? `HTTP ${status}`);
return { json: {
  disparo_id: l.disparo_id, mailing_id: l.mailing_id, nome: l.nome, telefone: l.telefone,
  template_name: l.template_name, mensagem: l.mensagem, ok, retry, wamid, erro,
} };

// O Postgres devolve o resultado do insert. Aqui devolvemos o resultado do envio,
// para que o fim do loop (Só enviados / Só erros) continue recebendo os dados certos.
return { json: $('Resultado Meta').item.json };

